<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue';
import { supabase, configured } from './supabase';
import { BookHeart, Heart, Images, MessageCircleHeart, LogOut, Trash2, Pencil, Home, CalendarHeart, LockKeyhole } from 'lucide-vue-next';
const session=ref(null), email=ref(''), password=ref(''), authMode=ref('login'), busy=ref(false), notice=ref('');
const tab=ref('home'), entries=ref([]), moods=ref([]), messages=ref([]), memories=ref([]);
const diaryText=ref(''), diaryTitle=ref(''), editId=ref(null), mood=ref('🙂'), messageText=ref(''), memoryTitle=ref(''), memoryText=ref(''), memoryFile=ref(null);
const profile=ref(null), displayName=ref(''), spaceId=ref(null), isOwner=ref(false), inviteCode=ref(''), inviteInput=ref(''), spaceName=ref('我们的拾光小屋');
const photoUrls=ref({});
const today=new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'});
const greeting=computed(()=>new Date().getHours()<12?'早上好':'今天辛苦啦');
const tabs=[{id:'home',label:'首页',icon:Home},{id:'diary',label:'日记',icon:BookHeart},{id:'mood',label:'心情',icon:CalendarHeart},{id:'messages',label:'留言',icon:MessageCircleHeart},{id:'memories',label:'回忆',icon:Images}];
function report(e){notice.value=e?.message||String(e)}
async function auth(){if(!configured)return;busy.value=true;notice.value='';try{const fn=authMode.value==='login'?'signInWithPassword':'signUp';const {error,data}=await supabase.auth[fn]({email:email.value,password:password.value});if(error)throw error;if(fn==='signUp'&&!data.session)notice.value='注册成功，请先到邮箱验证，再登录。'}catch(e){report(e)}finally{busy.value=false}}
async function logout(){await supabase.auth.signOut()}
async function load(){if(!session.value)return;try{const uid=session.value.user.id;const p=await supabase.from('profiles').select('*').eq('id',uid).maybeSingle();if(p.error)throw p.error;profile.value=p.data;displayName.value=p.data?.nickname||'';
const member=await supabase.from('space_members').select('space_id').eq('user_id',uid).maybeSingle();if(member.error)throw member.error;spaceId.value=member.data?.space_id||null;isOwner.value=false;
if(spaceId.value){const owner=await supabase.from('spaces').select('created_by').eq('id',spaceId.value).single();if(owner.error)throw owner.error;isOwner.value=owner.data.created_by===uid;}
const requests=[supabase.from('diaries').select('*').order('created_at',{ascending:false}),supabase.from('moods').select('*').order('day',{ascending:false})];
if(spaceId.value){requests.push(supabase.from('messages').select('*').eq('space_id',spaceId.value).order('created_at',{ascending:false}),supabase.from('memories').select('*').eq('space_id',spaceId.value).order('created_at',{ascending:false}));}
const results=await Promise.all(requests);for(const r of results)if(r.error)throw r.error;entries.value=results[0].data||[];moods.value=results[1].data||[];messages.value=results[2]?.data||[];memories.value=results[3]?.data||[];
}catch(e){report(e)}}
async function saveName(){try{const {error}=await supabase.from('profiles').update({nickname:displayName.value.trim().slice(0,40)||'拾光用户'}).eq('id',session.value.user.id);if(error)throw error;await load();notice.value='昵称已保存'}catch(e){report(e)}}
async function createSpace(){try{const {error}=await supabase.rpc('create_my_space',{space_name:spaceName.value});if(error)throw error;await refresh();notice.value='共享空间已创建，可以生成邀请码了'}catch(e){report(e)}}
async function generateInvite(){try{const {data,error}=await supabase.rpc('generate_space_invite',{target_space:spaceId.value});if(error)throw error;inviteCode.value=data;notice.value='邀请码有效期 24 小时，请私下发送给朋友'}catch(e){report(e)}}
async function connect(){try{const {error}=await supabase.rpc('join_space_by_invite',{invite_code:inviteInput.value.trim()});if(error)throw error;inviteInput.value='';await refresh();notice.value='加入成功！现在可以共享留言和回忆。'}catch(e){report(e)}}
async function saveDiary(){if(!diaryTitle.value.trim()&&!diaryText.value.trim())return;try{const row={title:diaryTitle.value.trim().slice(0,120)||'无题',content:diaryText.value};const q=editId.value?supabase.from('diaries').update(row).eq('id',editId.value):supabase.from('diaries').insert({...row,user_id:session.value.user.id});const {error}=await q;if(error)throw error;diaryTitle.value='';diaryText.value='';editId.value=null;await load();notice.value='日记已保存'}catch(e){report(e)}}
function editDiary(d){editId.value=d.id;diaryTitle.value=d.title;diaryText.value=d.content;window.scrollTo({top:0,behavior:'smooth'})}
async function remove(table,id){if(!confirm('确定删除这条记录吗？'))return;try{const row=table==='memories'?memories.value.find(x=>x.id===id):null;const {error}=await supabase.from(table).delete().eq('id',id);if(error)throw error;if(row?.image_path){const del=await supabase.storage.from('memories').remove([row.image_path]);if(del.error)report(del.error)}await refresh()}catch(e){report(e)}}
async function saveMood(){try{const {error}=await supabase.from('moods').upsert({user_id:session.value.user.id,day:new Date().toLocaleDateString('en-CA'),emoji:mood.value},{onConflict:'user_id,day'});if(error)throw error;await load();notice.value='今天的心情已记录'}catch(e){report(e)}}
async function sendMessage(){if(!messageText.value.trim()||!spaceId.value)return;try{const {error}=await supabase.from('messages').insert({space_id:spaceId.value,user_id:session.value.user.id,content:messageText.value.trim().slice(0,3000)});if(error)throw error;messageText.value='';await load()}catch(e){report(e)}}
async function addMemory(){if(!memoryTitle.value.trim()||!spaceId.value)return;busy.value=true;let uploadedPath=null;try{let image_path=null;if(memoryFile.value){const f=memoryFile.value;const allowed={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'};if(!allowed[f.type]||f.size>5*1024*1024)throw new Error('仅支持不超过 5MB 的 JPG、PNG、WebP 图片');image_path=`${spaceId.value}/${session.value.user.id}/${crypto.randomUUID()}.${allowed[f.type]}`;const up=await supabase.storage.from('memories').upload(image_path,f,{contentType:f.type});if(up.error)throw up.error;uploadedPath=image_path;}const {error}=await supabase.from('memories').insert({space_id:spaceId.value,user_id:session.value.user.id,title:memoryTitle.value.trim().slice(0,120),description:memoryText.value,image_path});if(error)throw error;memoryTitle.value='';memoryText.value='';memoryFile.value=null;await refresh();notice.value='回忆已收藏'}catch(e){if(uploadedPath)await supabase.storage.from('memories').remove([uploadedPath]);report(e)}finally{busy.value=false}}
async function loadPhotos(){if(!supabase)return;const paths=memories.value.filter(x=>x.image_path).map(x=>x.image_path);photoUrls.value={};for(const m of paths){const {data,error}=await supabase.storage.from('memories').createSignedUrl(m,3600);if(!error)photoUrls.value[m]=data.signedUrl}}
async function refresh(){await load();await loadPhotos()}
let subscription;
onMounted(async()=>{if(!configured)return;const {data}=await supabase.auth.getSession();session.value=data.session;if(session.value)await refresh();const {data:listener}=supabase.auth.onAuthStateChange((_,s)=>{session.value=s;if(s)queueMicrotask(()=>refresh());else{profile.value=null;spaceId.value=null;entries.value=[];moods.value=[];messages.value=[];memories.value=[]}});subscription=listener.subscription});onUnmounted(()=>subscription?.unsubscribe());
const formatDate=(s)=>new Date(s).toLocaleDateString('zh-CN',{month:'short',day:'numeric',year:'numeric'});
</script>
<template>
<div class="shell">
<header class="top"><div class="brand"><span class="brand-mark">✿</span><div><strong>拾光日记</strong><small>Little Moments</small></div></div><div class="top-right"><span class="top-date">{{today}}</span><button v-if="session" class="icon-btn" title="退出登录" @click="logout"><LogOut :size="18"/></button></div></header>
<main v-if="!configured" class="center"><div class="flower">🌷</div><h1>欢迎来到拾光日记</h1><p>项目已经准备好。请先按照 README 配置 Supabase 环境变量。</p></main>
<main v-else-if="!session" class="center auth"><div class="flower">🌼</div><h1>把平凡的日子，慢慢收藏起来。</h1><p>一方小天地，两个人的温柔回忆。</p><form @submit.prevent="auth"><label>邮箱<input type="email" v-model="email" autocomplete="email" required placeholder="你的邮箱"/></label><label>密码<input type="password" v-model="password" minlength="6" required placeholder="至少 6 位"/></label><button class="primary" :disabled="busy">{{busy?'请稍候…':authMode==='login'?'登录我的小天地':'创建账号'}}</button></form><button class="link" @click="authMode=authMode==='login'?'signup':'login'">{{authMode==='login'?'还没有账号？注册':'已有账号？返回登录'}}</button><p class="tiny">日记仅本人可见，共享内容仅连接的两位好友可见。</p></main>
<main v-else class="layout"><aside class="sidebar"><div class="side-title">我的小天地</div><button v-for="t in tabs" :key="t.id" :class="['nav-item',{active:tab===t.id}]" @click="tab=t.id;refresh()"><component :is="t.icon" :size="19"/>{{t.label}}</button><div class="side-note">“每一个普通的日子，都值得被珍藏。”</div></aside><section class="content">
<div v-if="notice" class="notice" role="status">{{notice}} <button @click="notice=''">×</button></div>
<template v-if="tab==='home'"><div class="eyebrow">{{today}}</div><h1>{{greeting}}，{{profile?.nickname||'亲爱的朋友'}} ☀️</h1><p class="sub">愿今天也有值得记录的小小幸福。</p><div class="hero"><span class="hero-icon">🌿</span><div><h2>生活是一本慢慢写的书</h2><p>不必每一天都精彩，但每一天都值得留下痕迹。</p></div></div><div class="cards"><button class="feature" @click="tab='diary'"><BookHeart/><strong>写一篇日记</strong><span>和今天的自己聊聊天</span></button><button class="feature" @click="tab='mood'"><CalendarHeart/><strong>记录心情</strong><span>给此刻一个小表情</span></button><button class="feature" @click="tab='messages'"><MessageCircleHeart/><strong>友情留言板</strong><span>留下一句想说的话</span></button><button class="feature" @click="tab='memories'"><Images/><strong>共同回忆</strong><span>收藏我们的故事</span></button></div><div class="panel"><h3>我们的双人空间 <Heart :size="17"/></h3><p>你的私人日记不会分享给对方。只有留言板和回忆馆是共同空间。</p><div class="form-row"><input v-model="displayName" placeholder="我的昵称" maxlength="40"/><button @click="saveName">保存昵称</button></div><div v-if="!spaceId" class="panel"><h3>建立我们的双人空间</h3><div class="form-row"><input v-model="spaceName" maxlength="50" placeholder="空间名称"/><button @click="createSpace">创建空间</button></div><p class="tiny">如果朋友已经创建空间，请在下方输入邀请码加入。</p></div><div v-if="spaceId && isOwner" class="code-row"><span>邀请好友加入（24小时有效）</span><button @click="generateInvite">生成新邀请码</button><code v-if="inviteCode">{{inviteCode}}</code></div><div v-if="!spaceId" class="form-row"><input v-model="inviteInput" placeholder="输入朋友发来的邀请码"/><button @click="connect">加入空间</button></div><p v-if="spaceId" class="hint">✓ 已加入双人空间。留言和回忆仅空间成员可见。</p><p class="tiny">请私下发送邀请码，不要公开分享。</p></div></template>
<template v-if="tab==='diary'"><div class="eyebrow">PRIVATE JOURNAL</div><h1>我的私人日记 <LockKeyhole :size="23"/></h1><p class="sub">这里的每一个字，都只属于你。</p><div class="panel"><h3>{{editId?'编辑日记':'写下今天的故事'}} ✍️</h3><input v-model="diaryTitle" maxlength="120" placeholder="给今天起个名字…"/><textarea v-model="diaryText" rows="7" placeholder="今天发生了什么？有什么想法想留下？"></textarea><div class="actions"><button class="primary" @click="saveDiary">{{editId?'保存修改':'保存日记'}}</button><button v-if="editId" @click="editId=null;diaryTitle='';diaryText=''">取消编辑</button></div></div><h3>过去的日子</h3><p v-if="!entries.length" class="empty">还没有日记，写下第一篇吧 🌱</p><article v-for="d in entries" :key="d.id" class="panel entry"><small>{{formatDate(d.created_at)}}</small><h3>{{d.title}}</h3><p class="preserve">{{d.content}}</p><div class="actions"><button @click="editDiary(d)"><Pencil :size="15"/> 编辑</button><button @click="remove('diaries',d.id)"><Trash2 :size="15"/> 删除</button></div></article></template>
<template v-if="tab==='mood'"><div class="eyebrow">MOOD TRACKER</div><h1>今天的心情 ☁️</h1><p class="sub">允许自己有各种各样的情绪。</p><div class="panel"><h3>今天是什么天气般的心情？</h3><div class="mood-row"><button v-for="e in ['😄','🙂','😐','😔','😫']" :key="e" :class="['mood',{selected:mood===e}]" @click="mood=e">{{e}}</button></div><button class="primary" @click="saveMood">记录今天</button></div><div class="panel"><h3>我的心情足迹</h3><p v-if="!moods.length" class="empty">还没有记录哦</p><div v-for="m in moods" :key="m.id" class="mood-record"><span>{{m.day}}</span><span>{{m.emoji}}</span></div></div></template>
<template v-if="tab==='messages'"><div class="eyebrow">FRIENDSHIP NOTES</div><h1>友情留言板 💌</h1><p class="sub">有些话，写下来就不会被时间吹散。</p><div v-if="!spaceId" class="panel">先在首页通过邀请码连接好友，才能使用共同空间。</div><template v-else><div class="panel"><textarea v-model="messageText" rows="4" maxlength="3000" placeholder="给朋友留一句话吧…"></textarea><button class="primary" @click="sendMessage">留下这句话</button></div><p v-if="!messages.length" class="empty">还没有留言，送出第一句祝福吧。</p><article v-for="m in messages" :key="m.id" class="panel entry"><small>{{m.user_id===session.user.id?'我':'朋友'}} · {{formatDate(m.created_at)}}</small><p class="preserve">{{m.content}}</p><button v-if="m.user_id===session.user.id" @click="remove('messages',m.id)"><Trash2 :size="15"/> 删除</button></article></template></template>
<template v-if="tab==='memories'"><div class="eyebrow">OUR LITTLE MEMORIES</div><h1>共同回忆馆 📷</h1><p class="sub">那些一起走过的日子，值得被好好珍藏。</p><div v-if="!spaceId" class="panel">先在首页通过邀请码连接好友，才能使用共同空间。</div><template v-else><div class="panel"><input v-model="memoryTitle" maxlength="120" placeholder="这段回忆的标题"/><textarea v-model="memoryText" rows="4" placeholder="记录这个故事…"></textarea><label class="upload">选择一张照片（可选，最大 5MB）<input type="file" accept="image/png,image/jpeg,image/webp" @change="memoryFile=$event.target.files[0]||null"/></label><button class="primary" :disabled="busy" @click="addMemory">{{busy?'保存中…':'收藏这段回忆'}}</button></div><p v-if="!memories.length" class="empty">我们的故事，从这里开始。</p><article v-for="m in memories" :key="m.id" class="panel entry"><img v-if="m.image_path&&photoUrls[m.image_path]" :src="photoUrls[m.image_path]" class="memory-photo" alt="共同回忆照片"/><small>{{m.user_id===session.user.id?'我':'朋友'}} · {{formatDate(m.created_at)}}</small><h3>{{m.title}}</h3><p class="preserve">{{m.description}}</p><button v-if="m.user_id===session.user.id" @click="remove('memories',m.id)"><Trash2 :size="15"/> 删除</button></article></template></template>
</section></main><nav v-if="session" class="mobile-nav"><button v-for="t in tabs" :key="t.id" :class="{active:tab===t.id}" @click="tab=t.id;refresh()"><component :is="t.icon" :size="21"/><span>{{t.label}}</span></button></nav><footer>Little Moments · 把日子过成喜欢的样子 ✿</footer></div>
</template>
